 login():void{this.http.post<any>('/api/v1/auth/login',{email:this.email,password:this.password,mfaCode:this.mfaCode||null,rememberMe:this.rememberMe}).subscribe({next:r=>{if(r.role==='CUSTOMER'){this.error=this.t('authAdministratorRequired');return;}this.token=r.accessToken;this.clearStoredTokens();const storage=this.rememberMe?localStorage:sessionStorage;storage.setItem('artio-admin-token',r.accessToken);storage.setItem('artio-admin-email',this.email);if(r.mfaEnrollmentRequired){this.mfaSetupRequired=true;this.beginMfaEnrollment();return;}this.mfaSetupRequired=false;this.loadAuthenticatedWorkspace();},error:e=>this.error=e.error?.message??this.t('authSignInFailure')})}
