  loadProducts(silent=false):void{const params=new URLSearchParams({page:String(this.catalogPage),size:String(this.catalogSize),state:this.catalogState,sort:this.catalogSort,direction:this.catalogDirection});if(this.query.trim())params.set('q',this.query.trim());if(this.catalogBrandId)params.set('brandId',this.catalogBrandId);if(this.catalogCategoryId)params.set('categoryId',this.catalogCategoryId);const showLoading=!silent&&!this.products.length;if(showLoading){this.productsLoading=true;this.updateProductCatalogInputs()}this.http.get<{items:Product[];total:number}>(`/api/v1/admin/catalog/products?${params}`).subscribe({next:r=>{let items=r.items;if(this.pendingCreatedProduct){if(items.some(product=>product.id===this.pendingCreatedProduct!.id))this.pendingCreatedProduct=null;else items=[this.pendingCreatedProduct,...items.filter(product=>product.id!==this.pendingCreatedProduct!.id)].slice(0,this.catalogSize)}this.products=items;this.catalogTotal=Math.max(r.total,this.products.length);if(showLoading)this.productsLoading=false;const pendingActionId=this.catalogActionPendingId;let variantsPending=this.products.length;const finishVariants=()=>{if(--variantsPending===0&&this.catalogActionPendingId===pendingActionId){this.catalogActionPendingId=null;this.updateProductCatalogInputs()}};if(!variantsPending)this.catalogActionPendingId=null;this.updateProductCatalogInputs();for(const p of this.products)this.http.get<Array<{id:string;name:string;sku:string;active:boolean}>>(`/api/v1/products/${p.id}/variants`).subscribe({next:v=>{p.variants=v;this.updateProductCatalogInputs();finishVariants()},error:()=>{p.variants=[];this.updateProductCatalogInputs();finishVariants()}})},error:e=>{if(showLoading){this.productsLoading=false;this.catalogActionPendingId=null;this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateProductCatalogInputs()}}})}
