 invokeExtension():void{if(!this.selectedExtension)return;let payload:any;try{payload=JSON.parse(this.extensionInvocation.payloadJson)}catch{this.error=this.t('adminInvalidJson');this.updateExtensionAdminInputs();return}const body={...this.extensionInvocation,payload,idempotencyKey:crypto.randomUUID(),deadlineMillis:5000};this.http.post<any>('/api/v1/admin/extensions/'+this.selectedExtension.manifest.id+'/invoke',body).subscribe({next:r=>{this.extensionInvocationResult=r;this.error='';this.updateExtensionAdminInputs()},error:e=>{this.extensionInvocationResult=null;this.error=e.error?.message??e.error?.detail??e.error?.message??'Extension diagnostic request failed.';this.updateExtensionAdminInputs()}})}
