 submitLoyaltyAdjustment():void{const selection=this.selectedLoyalty;const points=Number(this.loyaltyAdjustmentPoints);const reason=this.loyaltyAdjustmentReason.trim();if(!selection||!this.loyaltyAdjustmentDialog||this.loyaltyAdjustmentBusy)return;if(!this.enterpriseFeatures.includes('LOYALTY')){this.loyaltyAdjustmentError=this.t('loyaltyAdjustLicenseRequired');return}if(!Number.isInteger(points)||points===0||Math.abs(points)>1000000){this.loyaltyAdjustmentError=this.t('loyaltyAdjustInvalidPoints');return}if(!reason){this.loyaltyAdjustmentError=this.t('loyaltyAdjustReasonRequired');return}const user=selection.user;const storageKey=`artio-loyalty-adjust:${user.id}:${points}`;let key=sessionStorage.getItem(storageKey);if(!key){key=crypto.randomUUID();sessionStorage.setItem(storageKey,key)}this.loyaltyAdjustmentBusy=true;this.loyaltyAdjustmentError='';this.http.post<any>(`/api/v1/admin/loyalty/${user.id}/adjust`,{points,reason},{headers:{'Idempotency-Key':key}}).subscribe({next:account=>{sessionStorage.removeItem(storageKey);this.selectedLoyalty={user,account};this.loyaltyAdjustmentBusy=false;this.loyaltyAdjustmentRef?.nativeElement.close()},error:e=>{this.loyaltyAdjustmentBusy=false;this.loyaltyAdjustmentError=e.error?.message??e.error?.detail??this.t('loyaltyAdjustFailure')}})}
  exportProducts():void{if(!this.isSuperadmin)return;this.exportingProducts=true;this.error='';this.updateDataTransferAdminInputs();this.http.get('/api/v1/admin/catalog/products/export',{responseType:'blob'}).subscribe({next:blob=>{const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='artio-products.csv';anchor.click();window.setTimeout(()=>URL.revokeObjectURL(url),0);this.exportingProducts=false;this.updateDataTransferAdminInputs()},error:e=>{this.exportingProducts=false;this.error=e.error?.message??e.error?.detail??this.t('adminExportFailure');this.updateDataTransferAdminInputs()}})}
 importProducts(event:Event):void{if(!this.isSuperadmin)return;const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;if(!file.name.toLowerCase().endsWith('.csv')){this.error=this.t('adminInvalidCsv');this.updateDataTransferAdminInputs();return}const form=new FormData();form.append('file',file,file.name);this.importingProducts=true;this.productImportReport=null;this.error='';this.updateDataTransferAdminInputs();this.http.post<any>('/api/v1/admin/catalog/products/import',form).subscribe({next:report=>{this.productImportReport=report;this.error='';this.importingProducts=false;this.updateDataTransferAdminInputs()},error:e=>{this.importingProducts=false;this.error=e.error?.message??e.error?.detail??this.t('adminImportFailure');this.updateDataTransferAdminInputs()}})}

 productEditorTitle():string{const kind=this.productEditorDialog?.kind;return this.t(kind==='duplicate'?'productEditorDuplicateTitle':kind==='variantCreate'?'productEditorVariantCreateTitle':kind==='variantEdit'?'productEditorVariantEditTitle':kind==='schedule'?'productEditorScheduleTitle':'productEditorSeoDialogTitle')}
 openProductEditor(kind:'duplicate'|'variantCreate'|'variantEdit'|'schedule'|'seo',item:any):void{this.productEditorDialog={kind,item};this.productEditorName=kind==='duplicate'?item.name+' copy':kind==='variantEdit'?item.name:'';this.productEditorSku=kind==='duplicate'?item.sku+'-COPY':kind==='variantEdit'?item.sku:'';this.productEditorAttributes=JSON.stringify(item.attributes??{},null,2);const future=new Date(item.scheduledPublishAt??Date.now()+3600000);this.productEditorPublishAt=kind==='schedule'?new Date(future.getTime()-future.getTimezoneOffset()*60000).toISOString().slice(0,16):'';this.productEditorSlug=item.seoSlug??item.name?.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/,'');this.productEditorSeoTitle=item.seoTitle??item.name??'';this.productEditorSeoDescription=item.seoDescription??item.description??'';this.productEditorError='';this.productEditorBusy=false;setTimeout(()=>{if(this.productEditorDialog&&!this.productEditorRef?.nativeElement.open)this.productEditorRef?.nativeElement.showModal()},0)}
 cancelProductEditor(event:Event):void{if(this.productEditorBusy)event.preventDefault()}
 productEditorClosed():void{if(this.productEditorBusy)return;this.productEditorDialog=null;this.productEditorError=''}
 closeProductEditor():void{if(!this.productEditorBusy)this.productEditorRef?.nativeElement.close()}
 submitProductEditor():void{const state=this.productEditorDialog;if(!state||this.productEditorBusy)return;const kind=state.kind;const item=state.item;let request:any;if(kind==='duplicate'){const name=this.productEditorName.trim();const sku=this.productEditorSku.trim();if(!name||!sku){this.productEditorError=this.t('productEditorRequired');return}request=this.http.post<Product>(`/api/v1/products/${item.id}/duplicate`,{name,description:item.description,sku})}else if(kind==='variantCreate'||kind==='variantEdit'){const name=this.productEditorName.trim();const sku=this.productEditorSku.trim();if(!name||!sku){this.productEditorError=this.t('productEditorRequired');return}const attributes=this.parseVariantAttributes(this.productEditorAttributes);if(attributes===null)return;const body={name,sku,attributes};request=kind==='variantCreate'?this.http.post(`/api/v1/products/${item.id}/variants`,body):this.http.put(`/api/v1/variants/${item.id}`,body)}else if(kind==='schedule'){const publishAt=new Date(this.productEditorPublishAt);if(Number.isNaN(publishAt.getTime())||publishAt.getTime()<=Date.now()){this.productEditorError=this.t('productEditorFutureDate');return}request=this.http.put(`/api/v1/products/${item.id}/publication-schedule`,{publishAt:publishAt.toISOString()})}else{const slug=this.productEditorSlug.trim();if(!slug){this.productEditorError=this.t('productEditorRequired');return}request=this.http.put(`/api/v1/products/${item.id}/seo`,{slug,title:this.productEditorSeoTitle.trim()||null,description:this.productEditorSeoDescription.trim()||null})}this.productEditorBusy=true;this.productEditorError='';request.subscribe({next:()=>{this.productEditorBusy=false;this.productEditorRef?.nativeElement.close();this.loadProducts();if(kind==='duplicate')this.success=this.t('productEditorDuplicateSuccess')},error:(e:any)=>{this.productEditorBusy=false;this.productEditorError=e.error?.message??e.error?.detail??this.t('productEditorFailure')}})}
