 toggle(p:Product):void{if(this.catalogActionPendingId)return;this.catalogActionPendingId=p.id;this.updateProductCatalogInputs();this.http.put(`/api/v1/products/${p.id}/active`,{active:!p.active}).subscribe({next:()=>this.loadProducts(),error:e=>{this.catalogActionPendingId=null;this.updateProductCatalogInputs();this.error=e.error?.message??e.error?.detail??this.t('adminUpdateFailure')}})}
 openProductActionDialog(kind:'archive'|'cancelPublication',product:Product):void{this.productActionDialog={kind,product};this.productActionDialogBusy=false;this.productActionDialogError='';setTimeout(()=>{const dialog=this.productActionDialogRef?.nativeElement;if(this.productActionDialog?.product?.id===product.id&&dialog&&!dialog.open)dialog.showModal()},0)}
 cancelProductActionDialog(event:Event):void{if(this.productActionDialogBusy)event.preventDefault()}
 productActionDialogClosed():void{if(this.productActionDialogBusy)return;this.productActionDialog=null;this.productActionDialogError=''}
