 submitProductAction():void{const action=this.productActionDialog;if(!action||this.productActionDialogBusy)return;this.productActionDialogBusy=true;this.productActionDialogError='';const request=action.kind==='archive'?this.http.put(`/api/v1/products/${action.product.id}/archive`,{}):this.http.delete(`/api/v1/products/${action.product.id}/publication-schedule`);request.subscribe({next:()=>{this.productActionDialogBusy=false;this.productActionDialogRef?.nativeElement.close();this.loadProducts()},error:e=>{this.productActionDialogBusy=false;this.productActionDialogError=e.error?.message??e.error?.detail??this.t('productActionFailure')}})}
