 parseVariantAttributes(raw:string):Record<string,string>|null{try{const value=JSON.parse(raw);if(!value||Array.isArray(value)||typeof value!=='object'||Object.values(value).some(item=>typeof item!=='string'))throw new Error();return value as Record<string,string>}catch{this.productEditorError=this.t('productEditorInvalidOptions');return null}}
 toggleVariant(variant:{id:string;active:boolean}):void{if(this.catalogActionPendingId)return;this.catalogActionPendingId=variant.id;this.updateProductCatalogInputs();this.http.put(`/api/v1/variants/${variant.id}/active`,{active:!variant.active}).subscribe({next:()=>this.loadProducts(),error:e=>{this.catalogActionPendingId=null;this.updateProductCatalogInputs();this.error=e.error?.message??e.error?.detail??this.t('adminUpdateFailure')}})}
