 editTranslations(product:Product):void{this.translationProduct=product;this.translationLocale='de';this.updateProductCatalogInputs();this.loadTranslation()}
 loadTranslation():void{if(!this.translationProduct)return;const generation=++this.translationLoadGeneration;this.translationLoading=true;this.translationError='';this.translationDraft={name:'',description:'',seoSlug:'',seoTitle:'',seoDescription:''};this.updateProductCatalogInputs();this.http.get<Array<{locale:string;name:string;description:string;seoSlug:string|null;seoTitle:string|null;seoDescription:string|null}>>(`/api/v1/products/${this.translationProduct.id}/translations`).subscribe({next:items=>{if(generation!==this.translationLoadGeneration)return;const found=items.find(item=>item.locale===this.translationLocale);if(found)this.translationDraft={name:found.name,description:found.description,seoSlug:found.seoSlug??'',seoTitle:found.seoTitle??'',seoDescription:found.seoDescription??''};this.translationLoading=false;this.updateProductCatalogInputs()},error:()=>{if(generation!==this.translationLoadGeneration)return;this.translationLoading=false;this.translationError=this.t('adminLoadFailure');this.updateProductCatalogInputs()}})}
