 registerExtension():void{try{const manifest=JSON.parse(this.extensionManifestJson);const endpoint=manifest?.packageManifest?'/api/v1/admin/extensions/register-v2':'/api/v1/admin/extensions/register';this.http.post(endpoint,manifest).subscribe({next:()=>{this.showExtensionRegistration=false;this.extensionManifestJson='';this.error='';this.loadExtensions()},error:e=>{this.error=e.error?.message??e.error?.detail??'Manifest validation or registration failed.';this.updateExtensionAdminInputs()}})}catch{this.error=this.t('adminInvalidJson');this.updateExtensionAdminInputs()}}
 selectExtension(extension:any):void{this.http.get<any>(`/api/v1/admin/extensions/${extension.id}`).subscribe({next:plugin=>{plugin.compatibilityModes=this.extensions.find(item=>item.id===extension.id)?.compatibilityModes??'LEGACY_V1';this.selectedExtension=plugin;this.extensionConfig={...plugin.configuration};for(const key of Object.keys(plugin.manifest.configuration??{})){if(plugin.manifest.configuration[key].type==='secret')this.extensionConfig[key]=''}this.loadV2Composition(plugin);this.updateExtensionAdminInputs()},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}})}
 private loadV2Composition(plugin:any):void{if(plugin.compatibilityModes!=='CAPABILITY_V2'){this.extensionInstances=[];this.extensionBindings=[];this.extensionSubscriptions=[];return}const id=plugin.manifest.id;this.http.get<any[]>(`/api/v1/admin/extensions/${id}/instances`).subscribe({next:r=>{this.extensionInstances=r;this.instanceConfigurations={...this.instanceConfigurations,...Object.fromEntries(r.map(instance=>[instance.instanceId,this.instanceConfigurations[instance.instanceId]??'{}']))};this.updateExtensionAdminInputs()},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}});this.http.get<any[]>(`/api/v1/admin/extensions/${id}/bindings`).subscribe({next:r=>{this.extensionBindings=r;this.updateExtensionAdminInputs()},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}});this.http.get<any[]>(`/api/v1/admin/extensions/${id}/subscriptions`).subscribe({next:r=>{this.extensionSubscriptions=r;this.updateExtensionAdminInputs()},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}})}
 private refreshV2Composition(plugin:any):void{this.loadV2Composition(plugin);this.loadExtensions()}
 private createV2Instance(action:Extract<ExtensionAdminAction,{type:'createInstance'}>):void{let configuration:any;try{configuration=JSON.parse(action.configurationJson)}catch{this.error=this.t('adminInvalidJson');return}this.http.post(`/api/v1/admin/extensions/${action.extension.manifest.id}/instances`,{instanceKey:action.instanceKey,configuration}).subscribe({next:()=>{this.error='';this.refreshV2Composition(action.extension)},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}})}
 private manageV2Instance(action:Extract<ExtensionAdminAction,{type:'instanceLifecycle'}>):void{if(action.action==='uninstall'){this.instanceUninstallAction=action;this.instanceUninstallError='';queueMicrotask(()=>this.instanceUninstallDialogRef?.nativeElement.showModal());return}this.executeV2Instance(action)}
 private executeV2Instance(action:Extract<ExtensionAdminAction,{type:'instanceLifecycle'}>):void{const id=action.extension.manifest.id;const url=`/api/v1/admin/extensions/${id}/instances/${action.instance.instanceId}`;const request=action.action==='install'?this.http.post('/api/v1/admin/extensions/installations',{pluginId:id,instanceId:action.instance.instanceId,idempotencyKey:crypto.randomUUID()}):this.http.post(`${url}/${action.action}`,{});request.subscribe({next:(result:any)=>{this.error='';if(action.action==='install')this.extensionHealth=`Installation queued · ${result.jobId}`;if(action.action==='uninstall'){this.instanceUninstallBusy=false;this.instanceUninstallDialogRef?.nativeElement.close()}this.refreshV2Composition(action.extension)},error:e=>{if(action.action==='uninstall'){this.instanceUninstallBusy=false;this.instanceUninstallError=e.error?.message??e.error?.detail??this.t('adminUpdateFailure')}else this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}})}
