 private saveV2InstanceConfiguration(action:Extract<ExtensionAdminAction,{type:'saveInstanceConfiguration'}>):void{let configuration:any;try{configuration=JSON.parse(action.configurationJson)}catch{this.error=this.t('adminInvalidJson');this.updateExtensionAdminInputs();return}this.http.put(`/api/v1/admin/extensions/${action.extension.manifest.id}/instances/${action.instance.instanceId}/configuration`,configuration).subscribe({next:()=>{this.error='';this.refreshV2Composition(action.extension)},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}})}
