 private updateV2SubscriptionState(action:Extract<ExtensionAdminAction,{type:'subscriptionState'}>):void{this.http.put(`/api/v1/admin/extensions/${action.extension.manifest.id}/subscriptions/${action.subscription.subscriptionId}/state`,{state:action.state}).subscribe({next:()=>{this.error='';this.refreshV2Composition(action.extension)},error:e=>{this.error=e.error?.message??e.error?.detail??this.t('adminLoadFailure');this.updateExtensionAdminInputs()}})}
 saveExtensionConfiguration():void{if(!this.selectedExtension)return;const payload={...this.extensionConfig};for(const key of this.selectedExtension.configuredSecrets){if(!payload[key])delete payload[key]}this.http.put(`/api/v1/admin/extensions/${this.selectedExtension.manifest.id}/configuration`,payload).subscribe({next:()=>{this.error='';this.selectedExtension=null;this.loadExtensions()},error:e=>{this.error=e.error?.message??e.error?.detail??'Extension configuration is invalid.';this.updateExtensionAdminInputs()}})}
 openObservability():void{const popup=window.open('about:blank','_blank');if(!popup){this.error='Allow pop-ups to open observability dashboards.';this.updateExtensionAdminInputs();return}popup.opener=null;this.http.get('/api/v1/admin/extensions/observability.artio/ui-session').subscribe({next:()=>{popup.location.href='/plugins/observability/'},error:e=>{popup.close();this.error=e.error?.message??e.error?.detail??this.t('adminOpenFailure');this.updateExtensionAdminInputs()}})}
 extensionAction(extension:any,action:'install'|'enable'|'disable'):void{const request=action==='install'?this.http.post('/api/v1/admin/extensions/installations',{pluginId:extension.id,idempotencyKey:crypto.randomUUID()}):this.http.post(`/api/v1/admin/extensions/${extension.id}/${action}`,{});request.subscribe({next:(result:any)=>{this.error='';this.extensionHealth=action==='install'?`Installation queued · ${result.jobId}`:'';this.loadExtensions()},error:e=>{this.error=e.error?.message??e.error?.detail??`Could not ${action} extension.`;this.updateExtensionAdminInputs()}})}
 extensionActionTitle():string{return this.t(this.extensionActionDialog?.kind==='update'?'extensionUpdateTitle':this.extensionActionDialog?.kind==='rollback'?'extensionRollbackTitle':'extensionUninstallTitle')}
