 openExtensionAction(kind:'update'|'rollback'|'uninstall',extension:any):void{this.extensionActionDialog={kind,extension};this.extensionNextManifest=kind==='update'?JSON.stringify(extension.manifest,null,2):'';this.extensionActionBusy=false;this.extensionActionError='';setTimeout(()=>{if(this.extensionActionDialog&&!this.extensionActionRef?.nativeElement.open)this.extensionActionRef?.nativeElement.showModal()},0)}
