 submitExtensionAction():void{const action=this.extensionActionDialog;if(!action||this.extensionActionBusy)return;const id=action.extension.id;let request:any;if(action.kind==='update'){try{const manifest=JSON.parse(this.extensionNextManifest);if(!manifest||Array.isArray(manifest)||typeof manifest!=='object')throw new Error();request=this.http.post(`/api/v1/admin/extensions/${id}/update`,manifest)}catch{this.extensionActionError=this.t('extensionManifestInvalid');return}}else if(action.kind==='rollback')request=this.http.post(`/api/v1/admin/extensions/${id}/rollback`,{});else request=this.http.delete(`/api/v1/admin/extensions/${id}`);this.extensionActionBusy=true;this.extensionActionError='';request.subscribe({next:()=>{this.extensionActionBusy=false;this.extensionActionRef?.nativeElement.close();this.error='';this.loadExtensions()},error:(e:any)=>{this.extensionActionBusy=false;this.extensionActionError=e.error?.message??e.error?.detail??this.t('extensionActionFailure')}})}
